ValidationRule.errorConditionFormula:
AND(
  OR(
    NOT( ISBLANK( SOL_Prazo_Contato__c ) ),
    AND(
      ISPICKVAL( SOL_Tipo_Tarefa__c , "Contato" ),
      ISPICKVAL( SOL_Canal_Contato__c , "Ligação" )
    )
  ),
  NOT(
    OR(
      ISPICKVAL( Status , "Completed" ),
      ISPICKVAL( Status , "Cancelada" )
    )
  ),
  ISPICKVAL( SOL_Resultado_Contato__c , "Atendeu" )
)
